1	package httpapi
2	
3	import (
4		"encoding/json"
5		"errors"
6		"io"
7		"net/http"
8		"net/http/httptest"
9		"strings"
10		"sync"
11		"testing"
12	
13		"github.com/cocosolocoder/signalroom/internal/events"
14		"github.com/cocosolocoder/signalroom/internal/metrics"
15	)
