88	func metricsDo(t *testing.T, server *httptest.Server, method, path, body string) (int, map[string]any) {
89		t.Helper()
90		var reader io.Reader
91		if body != "" {
92			reader = strings.NewReader(body)
93		}
94		req, err := http.NewRequest(method, server.URL+path, reader)
95		if err != nil {
96			t.Fatal(err)
97		}
98		if body != "" {
99			req.Header.Set("Content-Type", "application/json")
100		}
101		resp, err := http.DefaultClient.Do(req)
102		if err != nil {
103			t.Fatal(err)
104		}
105		defer resp.Body.Close()
106		raw, err := io.ReadAll(resp.Body)
107		if err != nil {
108			t.Fatal(err)
109		}
110		var out map[string]any
111		if err := json.Unmarshal(raw, &out); err != nil {
112			t.Fatalf("decode %q (%d): %v", raw, resp.StatusCode, err)
113		}
114		return resp.StatusCode, out
115	}
