126	func TestPostMetricsCreatedAndReplayed(t *testing.T) {
127		server := newMetricsServer(t, nil, nil)
128		body := `{"samples":[
129			{"id":"s1","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1},
