208			"/metrics/aggregate?name=requests&since=2026-10-01T10:00:00Z&until=2026-10-01T11:00:00Z&step=60", "")
209		if status != http.StatusServiceUnavailable {
210			t.Fatalf("aggregate must stay 503, got %d", status)
211		}
212		// Events are unaffected.
