196	// isJSONNumber validates the strict JSON number grammar, so a quoted string,
197	// NaN, or Infinity never reach the float parser.
198	func isJSONNumber(b []byte) bool {
199		i := 0
200		if i < len(b) && b[i] == '-' {
201			i++
202		}
203		if i >= len(b) {
204			return false
205		}
206		if b[i] == '0' {
207			i++
208		} else if b[i] >= '1' && b[i] <= '9' {
209			i++
210			for i < len(b) && b[i] >= '0' && b[i] <= '9' {
211				i++
212			}
213		} else {
214			return false
215		}
216		if i < len(b) && b[i] == '.' {
217			i++
218			if i >= len(b) || b[i] < '0' || b[i] > '9' {
219				return false
220			}
221			for i < len(b) && b[i] >= '0' && b[i] <= '9' {
222				i++
223			}
224		}
225		if i < len(b) && (b[i] == 'e' || b[i] == 'E') {
226			i++
227			if i < len(b) && (b[i] == '+' || b[i] == '-') {
228				i++
229			}
230			if i >= len(b) || b[i] < '0' || b[i] > '9' {
231				return false
232			}
233			for i < len(b) && b[i] >= '0' && b[i] <= '9' {
234				i++
235			}
236		}
237		return i == len(b)
238	}
