157		pendingPoint := make(map[seriesKey]map[pointKey]string, len(normalized))
158		var created []Sample
159		var result IngestResult
160		for _, sample := range normalized {
161			if _, repeated := pendingID[sample.ID]; repeated {
162				return IngestResult{}, &ConflictError{Reason: "sample id repeats within batch"}
163			}
164			pendingID[sample.ID] = struct{}{}
165	
166			key := keyFor(sample)
167			if existing, ok := s.byID[sample.ID]; ok {
168				if !sameContent(existing, sample) {
169					return IngestResult{}, &ConflictError{Reason: "sample id already exists with different content"}
