250	// keyFor builds the identity of a series from a normalized sample.
251	func keyFor(sample Sample) seriesKey {
252		return seriesKey{service: sample.Service, name: sample.Name, labels: labelsKey(sample.Labels)}
253	}
254	
255	// labelsKey renders a label set as a collision-free canonical string so two
256	// maps with the same complete set share a series regardless of iteration
257	// order. Name and value are each length-prefixed, which keeps values
258	// containing '=' or ';' from ever aliasing another set.
259	func labelsKey(labels map[string]string) string {
260		if len(labels) == 0 {
261			return ""
262		}
263		keys := make([]string, 0, len(labels))
264		for name := range labels {
265			keys = append(keys, name)
266		}
267		sort.Strings(keys)
268		var b strings.Builder
269		for _, name := range keys {
270			value := labels[name]
271			b.WriteString(strconv.Itoa(len(name)))
272			b.WriteByte(':')
273			b.WriteString(name)
274			b.WriteByte(',')
275			b.WriteString(strconv.Itoa(len(value)))
276			b.WriteByte(':')
277			b.WriteString(value)
278			b.WriteByte(';')
279		}
280		return b.String()
281	}
282	
283	// seriesState is one sorted run of (time, value, id) points sharing one
284	// label set.
285	type seriesState struct {
286		labels map[string]string
287		points []point
288	}
289	
290	type point struct {
291		at    time.Time
292		value float64
293		id    string
294	}
295	
296	// add inserts one point keeping the run ordered by time. Points at the same
297	// instant for one series are rejected upstream.
298	func (st *seriesState) add(sample Sample) {
299		p := point{at: sample.At, value: sample.Value, id: sample.ID}
300		idx := sort.Search(len(st.points), func(i int) bool {
301			return st.points[i].at.After(p.at)
302		})
303		st.points = append(st.points, point{})
304		copy(st.points[idx+1:], st.points[idx:])
305		st.points[idx] = p
306	}
307	
308	// pointOwner returns the id of the sample at exactly at, or "" when the point
309	// is absent. A nil receiver reports no owner.
310	func (st *seriesState) pointOwner(at time.Time) string {
311		if st == nil {
312			return ""
313		}
314		idx := sort.Search(len(st.points), func(i int) bool {
315			return !st.points[i].at.Before(at)
316		})
317		if idx < len(st.points) && st.points[idx].at.Equal(at) {
318			return st.points[idx].id
319		}
320		return ""
321	}
322	
323	// sameContent compares two normalized samples on their absolute instant,
324	// value, and label set. Numeric equality makes 1 and 1.0 identical; map
325	// comparison makes label key order irrelevant.
326	func sameContent(a, b Sample) bool {
327		return a.ID == b.ID &&
328			a.Service == b.Service &&
329			a.Name == b.Name &&
330			a.At.Equal(b.At) &&
331			a.Value == b.Value &&
332			maps.Equal(a.Labels, b.Labels)
333	}
