1	package events
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"time"
9	)
10	
11	// eventDTO is the wire and on-disk representation of an event. Timestamps use
12	// RFC3339Nano, which time.Time produces and accepts natively. Labels is
13	// omitted entirely when an event has none, so frames written before labels
14	// existed decode unchanged.
15	type eventDTO struct {
16		ID       string            `json:"id"`
17		Service  string            `json:"service"`
18		Severity string            `json:"severity"`
19		Message  string            `json:"message"`
20		At       time.Time         `json:"at"`
21		Labels   map[string]string `json:"labels,omitempty"`
22	}
23	
24	// decodeLabels strictly decodes a JSON labels member; DecodeLabelsObject is
25	// the exported form used by request bodies that carry the same shape, such as
26	// the label filters in an alert preview request.
27	func decodeLabels(raw json.RawMessage) (map[string]string, error) {
28		return DecodeLabelsObject(raw)
29	}
30	
31	// DecodeLabelsObject strictly decodes a JSON labels object: null, absent, or
32	// an object whose values are all strings, and duplicate names are rejected
33	// instead of silently overwriting each other the way a plain map decode
34	// would. Name/value content rules are enforced later by NormalizeLabels or
35	// filter normalization.
36	func DecodeLabelsObject(raw json.RawMessage) (map[string]string, error) {
37		if len(raw) == 0 || bytes.Equal(raw, []byte("null")) {
38			return nil, nil
39		}
40		dec := json.NewDecoder(bytes.NewReader(raw))
41		open, err := dec.Token()
42		if err != nil {
43			return nil, fmt.Errorf("decode labels: %w", err)
44		}
45		if delim, ok := open.(json.Delim); !ok || delim != '{' {
46			return nil, fmt.Errorf("decode labels: must be an object of string values")
47		}
48		labels := make(map[string]string)
49		for dec.More() {
50			keyToken, err := dec.Token()
51			if err != nil {
52				return nil, fmt.Errorf("decode labels: %w", err)
53			}
54			key, ok := keyToken.(string)
55			if !ok {
56				return nil, fmt.Errorf("decode labels: names must be strings")
57			}
58			if _, dup := labels[key]; dup {
59				return nil, fmt.Errorf("decode labels: duplicate label name %q", key)
60			}
61			var value *string
62			if err := dec.Decode(&value); err != nil {
63				return nil, fmt.Errorf("decode labels: value for %q must be a string", key)
64			}
65			if value == nil {
66				return nil, fmt.Errorf("decode labels: value for %q must be a string", key)
67			}
68			labels[key] = *value
69		}
70		if _, err := dec.Token(); err != nil { // closing '}'
71			return nil, fmt.Errorf("decode labels: %w", err)
72		}
73		if len(labels) == 0 {
74			return nil, nil
75		}
76		return labels, nil
77	}
78	
79	// allowedEventFields is the exact set of members each event object may
80	// carry; anything else is an unknown field.
81	var allowedEventFields = map[string]struct{}{
82		"id":       {},
83		"service":  {},
84		"severity": {},
85		"message":  {},
86		"at":       {},
87		"labels":   {},
88	}
89	
90	// MarshalBatch encodes normalized events as a JSON array with sorted keys.
91	func MarshalBatch(batch []Event) ([]byte, error) {
