96	func findAggSeries(t *testing.T, out []map[string]any, label string) map[string]any {
97		t.Helper()
98		for _, series := range out {
99			labels, ok := series["labels"].(map[string]any)
100			if ok && labels["a"] == label {
101				return series
102			}
103		}
104		t.Fatalf("series a=%q missing from %d series", label, len(out))
105		return nil
106	}
