108	func assertAggSegments(t *testing.T, series map[string]any, wantCounts []int, wantDeltas []float64) {
109		t.Helper()
110		rawSegs, ok := series["segments"].([]any)
111		if !ok || len(rawSegs) != len(wantCounts) {
112			t.Fatalf("segments shape: %v", series["segments"])
113		}
114		for i, rawSeg := range rawSegs {
115			seg := rawSeg.(map[string]any)
116			if seg["since"] != metricSegBounds[i][0] || seg["until"] != metricSegBounds[i][1] {
117				t.Fatalf("seg %d boundaries = %v..%v, want %s..%s",
118					i, seg["since"], seg["until"], metricSegBounds[i][0], metricSegBounds[i][1])
119			}
120			if int(seg["count"].(float64)) != wantCounts[i] {
121				t.Fatalf("seg %d count = %v, want %d", i, seg["count"], wantCounts[i])
122			}
123			if seg["delta"].(float64) != wantDeltas[i] {
124				t.Fatalf("seg %d delta = %v, want %v", i, seg["delta"], wantDeltas[i])
125			}
126		}
127	}
