129	// assertAggBefore pins the pre-submission response: exactly series a=1 and
130	// a=2, ordered by canonical label set, each with one in-window sample.
131	func assertAggBefore(t *testing.T, out []map[string]any) {
132		t.Helper()
133		if len(out) != 2 {
134			t.Fatalf("before the batch exactly two series exist, got %d: %+v", len(out), out)
135		}
136		if out[0]["service"] != "svc" || out[0]["labels"].(map[string]any)["a"] != "1" {
137			t.Fatalf("series order 0: %+v", out[0])
138		}
139		if out[1]["service"] != "svc" || out[1]["labels"].(map[string]any)["a"] != "2" {
140			t.Fatalf("series order 1: %+v", out[1])
141		}
142		assertAggSegments(t, findAggSeries(t, out, "1"), []int{1, 0, 0}, []float64{100, 0, 0})
143		assertAggSegments(t, findAggSeries(t, out, "2"), []int{1, 0, 0}, []float64{0, 0, 0})
144	}
