146	// assertAggAfter pins the complete post-submission response: the new series
147	// a=3 appears, late predecessors moved every first-segment delta, and the
148	// query-end samples stay excluded.
149	func assertAggAfter(t *testing.T, out []map[string]any) {
150		t.Helper()
151		if len(out) != 3 {
152			t.Fatalf("after the batch three series exist, got %d: %+v", len(out), out)
153		}
154		if out[0]["labels"].(map[string]any)["a"] != "1" ||
155			out[1]["labels"].(map[string]any)["a"] != "2" ||
156			out[2]["labels"].(map[string]any)["a"] != "3" {
157			t.Fatalf("series order must be a=1,a=2,a=3: %+v", out)
158		}
159		assertAggSegments(t, findAggSeries(t, out, "1"), []int{1, 1, 0}, []float64{1, 1, 0})
160		assertAggSegments(t, findAggSeries(t, out, "2"), []int{1, 0, 1}, []float64{20, 0, 23})
161		assertAggSegments(t, findAggSeries(t, out, "3"), []int{0, 1, 1}, []float64{0, 45, 10})
162	}
