164	func TestAggregateBeforeAfterBatchHTTP(t *testing.T) {
165		server := newMetricsServer(t, nil, nil)
166		if status, out := postSamplesRaw(t, server, metricScenarioSeed); status != http.StatusOK {
167			t.Fatalf("seed: %d %v", status, out)
168		} else if int(number(out["created"])) != 3 {
169			t.Fatalf("seed created=%v", out)
170		}
171	
172		status, before := aggregateGet(t, server, metricScenarioQuery)
173		if status != http.StatusOK {
174			t.Fatalf("aggregate before: %d %v", status, before)
175		}
176		assertAggBefore(t, before)
177	
178		if status, out := postSamplesRaw(t, server, metricScenarioBatch); status != http.StatusOK {
179			t.Fatalf("batch: %d %v", status, out)
180		} else if int(number(out["created"])) != 11 || int(number(out["replayed"])) != 0 {
181			t.Fatalf("batch counts: %v", out)
182		}
183	
184		// Once the successful POST has returned, the same query must reflect the
185		// complete post-submission dataset.
186		status, after := aggregateGet(t, server, metricScenarioQuery)
187		if status != http.StatusOK {
188			t.Fatalf("aggregate after: %d %v", status, after)
189		}
190		assertAggAfter(t, after)
191	
192		// Replaying the identical shuffled batch stores nothing and changes
193		// nothing: timestamps, not body order, drive the result.
194		if status, out := postSamplesRaw(t, server, metricScenarioBatch); status != http.StatusOK {
195			t.Fatalf("replay: %d %v", status, out)
196		} else if int(number(out["created"])) != 0 || int(number(out["replayed"])) != 11 {
197			t.Fatalf("replay counts: %v", out)
198		}
199		status, replayed := aggregateGet(t, server, metricScenarioQuery)
200		if status != http.StatusOK {
201			t.Fatalf("aggregate after replay: %d", status)
202		}
203		if !reflect.DeepEqual(replayed, after) {
204			t.Fatalf("replayed submission changed the aggregate:\n%+v\n%+v", replayed, after)
205		}
206	}
