215	// newSlowMetricsServer builds a metrics store pre-seeded with many irrelevant
216	// series in another service (all outside the scenario window) so one
217	// aggregate round trip takes long enough to overlap deterministically with a
218	// concurrent submission. The fillers never appear in the scenario result.
219	func newSlowMetricsServer(t *testing.T) (*httptest.Server, *metrics.Store, *fakeMetricStorage) {
220		t.Helper()
221		store := metrics.NewStore()
222		mstore := &fakeMetricStorage{}
223		base := time.Date(2026, 9, 1, 0, 0, 0, 0, time.UTC)
224		const fillers = 40000
225		batch := make([]metrics.Sample, 0, fillers)
226		for i := range fillers {
227			id := strconv.Itoa(i)
228			batch = append(batch, metrics.Sample{
229				ID:      "filler-" + id,
230				Service: "filler-svc",
231				Name:    "requests",
232				At:      base.Add(time.Duration(i) * time.Nanosecond),
233				Value:   float64(i),
234				Labels:  map[string]string{"i": id},
235			})
236		}
237		if _, err := store.Ingest(batch, nil); err != nil {
238			t.Fatalf("seed fillers: %v", err)
239		}
240		server := newMetricsServer(t, store, mstore)
241		return server, store, mstore
242	}
