244	// ensureSlowAggregateHTTP reports a round trip comfortably longer than the
245	// overlap sleep, seeding more filler series when the first chunk is too quick
246	// on a fast machine.
247	func ensureSlowAggregateHTTP(t *testing.T, server *httptest.Server, store *metrics.Store) time.Duration {
248		t.Helper()
249		roundTrip := func() time.Duration {
250			start := time.Now()
251			if status, _ := aggregateGet(t, server, metricScenarioQuery); status != http.StatusOK {
252				t.Fatalf("warmup aggregate: %d", status)
253			}
254			return time.Since(start)
255		}
256		var slowest time.Duration
257		for range 3 {
258			if d := roundTrip(); d > slowest {
259				slowest = d
260			}
261		}
262		if slowest >= 20*time.Millisecond {
263			return slowest
264		}
265		base := time.Date(2026, 9, 2, 0, 0, 0, 0, time.UTC)
266		total := 40000
267		for round := 0; round < 5; round++ {
268			const chunk = 40000
269			batch := make([]metrics.Sample, 0, chunk)
270			for i := range chunk {
271				id := strconv.Itoa(total + i)
272				batch = append(batch, metrics.Sample{
273					ID:      "filler2-" + id,
274					Service: "filler-svc",
275					Name:    "requests",
276					At:      base.Add(time.Duration(total+i) * time.Nanosecond),
277					Value:   float64(total + i),
278					Labels:  map[string]string{"j": id},
279				})
280			}
281			if _, err := store.Ingest(batch, nil); err != nil {
282				t.Fatalf("seed more fillers: %v", err)
283			}
284			total += chunk
285			for range 3 {
286				if d := roundTrip(); d > slowest {
287					slowest = d
288				}
289			}
290			if slowest >= 20*time.Millisecond {
291				return slowest
292			}
293		}
294		return slowest
295	}
