297	type aggCall struct {
298		status int
299		body   []map[string]any
300	}
301	
302	// TestAggregateOverlappingBatchCommitHTTP overlaps real aggregate requests
303	// with a batch held mid durable commit:
304	//
305	//   - An aggregate already scanning when the submission reaches the metric
306	//     store lock finishes with the complete pre-submission state.
307	//   - Every aggregate whose read lock is queued while the durable commit is
308	//     pending is allowed to wait (that wait is not an error) and then returns
309	//     the complete post-submission state.
310	//
311	// In no response may one series already count the batch while another still
312	// shows its pre-batch series set or segment vector.
313	func TestAggregateOverlappingBatchCommitHTTP(t *testing.T) {
314		server, store, mstore := newSlowMetricsServer(t)
315		if status, out := postSamplesRaw(t, server, metricScenarioSeed); status != http.StatusOK {
316			t.Fatalf("seed: %d %v", status, out)
317		}
318		status, before := aggregateGet(t, server, metricScenarioQuery)
319		if status != http.StatusOK {
320			t.Fatalf("aggregate before: %d", status)
321		}
322		assertAggBefore(t, before)
323		scanTime := ensureSlowAggregateHTTP(t, server, store)
324	
325		earlyCh := make(chan aggCall, 1)
326		go func() {
327			st, body := aggregateGet(t, server, metricScenarioQuery)
328			earlyCh <- aggCall{st, body}
329		}()
330		time.Sleep(scanTime / 2)
331	
332		release, entered := mstore.armStall()
333		postCh := make(chan aggCall, 1)
334		go func() {
335			st, out := postSamplesRaw(t, server, metricScenarioBatch)
336			postCh <- aggCall{st, []map[string]any{out}}
337		}()
338		<-entered
339	
340		// The commit hook is holding the metric store write lock. Aggregates
341		// launched here queue behind it, wait out the commit, and scan afterwards,
342		// deterministically pinning the post-submission state.
343		const readers = 8
344		var wg sync.WaitGroup
345		calls := make([]aggCall, readers)
346		for i := range readers {
347			wg.Add(1)
348			go func(i int) {
349				defer wg.Done()
350				st, body := aggregateGet(t, server, metricScenarioQuery)
351				calls[i] = aggCall{st, body}
352			}(i)
353		}
354		time.Sleep(30 * time.Millisecond)
355		close(release)
356	
357		posted := <-postCh
358		if posted.status != http.StatusOK {
359			t.Fatalf("batch status=%d body=%v", posted.status, posted.body)
360		}
361		if created := int(posted.body[0]["created"].(float64)); created != 11 {
362			t.Fatalf("batch created=%d, want 11", created)
363		}
364		wg.Wait()
365	
366		status, after := aggregateGet(t, server, metricScenarioQuery)
367		if status != http.StatusOK {
368			t.Fatalf("aggregate after: %d", status)
369		}
370		assertAggAfter(t, after)
371		if reflect.DeepEqual(before, after) {
372			t.Fatal("pre- and post-batch aggregates must differ")
373		}
374		for i, call := range calls {
375			if call.status != http.StatusOK {
376				t.Fatalf("queued aggregate %d status=%d: waiting out a commit must not be an error", i, call.status)
377			}
378			if !reflect.DeepEqual(call.body, after) {
379				t.Fatalf("queued aggregate %d must show the complete post-batch state:\n%+v\n%+v",
380					i, call.body, after)
381			}
382		}
383	
384		// The aggregate in flight when the submission started must be exactly one
385		// whole state: fully pre-batch or fully post-batch, never a splice.
386		early := <-earlyCh
387		if early.status != http.StatusOK {
388			t.Fatalf("overlapping aggregate status=%d", early.status)
389		}
390		pre := reflect.DeepEqual(early.body, before)
391		post := reflect.DeepEqual(early.body, after)
392		if !pre && !post {
393			t.Fatalf("overlapping aggregate must be the complete pre- or post-batch state, got a splice:\n%+v", early.body)
394		}
395	}
