397	// TestAggregateUnchangedAfterConflictBatchesHTTP covers the 409 contract:
398	// one different-id sample claiming a stored (series, instant) point rejects
399	// the whole submission; none of its other samples may appear, and the segment
400	// counts and deltas stay byte-for-byte at their pre-submission values. A
401	// repeated id inside the batch behaves identically. Only a later clean batch
402	// moves the aggregate to its full post state.
403	func TestAggregateUnchangedAfterConflictBatchesHTTP(t *testing.T) {
404		mstore := &fakeMetricStorage{}
405		server := newMetricsServer(t, nil, mstore)
406		if status, out := postSamplesRaw(t, server, metricScenarioSeed); status != http.StatusOK {
407			t.Fatalf("seed: %d %v", status, out)
408		} else if int(number(out["created"])) != 3 {
409			t.Fatalf("seed counts: %v", out)
410		}
411		status, before := aggregateGet(t, server, metricScenarioQuery)
412		if status != http.StatusOK {
413			t.Fatalf("aggregate before: %d", status)
414		}
415		assertAggBefore(t, before)
416	
417		if status, out := postSamplesRaw(t, server, metricScenarioConflictBatch); status != http.StatusConflict {
418			t.Fatalf("series/time clash must be 409, got %d %v", status, out)
419		} else if out["error"] == "" {
420			t.Fatalf("409 needs a non-empty error: %v", out)
421		}
422		status, afterConflict := aggregateGet(t, server, metricScenarioQuery)
423		if status != http.StatusOK {
424			t.Fatalf("aggregate after conflict: %d", status)
425		}
426		if !reflect.DeepEqual(afterConflict, before) {
427			t.Fatalf("409 batch must leave the aggregate untouched:\n%+v\n%+v", afterConflict, before)
428		}
429	
430		if status, out := postSamplesRaw(t, server, metricScenarioDuplicateBatch); status != http.StatusConflict {
431			t.Fatalf("in-batch duplicate id must be 409, got %d %v", status, out)
432		}
433		status, afterDuplicate := aggregateGet(t, server, metricScenarioQuery)
434		if status != http.StatusOK {
435			t.Fatalf("aggregate after duplicate: %d", status)
436		}
437		if !reflect.DeepEqual(afterDuplicate, before) {
438			t.Fatalf("duplicate-id batch must leave the aggregate untouched:\n%+v", afterDuplicate)
439		}
440	
441		// Rejected submissions never reach durable storage: only the seed batch
442		// was persisted.
443		if len(mstore.batches) != 1 || len(mstore.batches[0]) != 3 {
444			t.Fatalf("rejected batches must persist nothing, got %d batches", len(mstore.batches))
445		}
446	
447		// A clean submission still moves the aggregate to the full post state.
448		if status, out := postSamplesRaw(t, server, metricScenarioBatch); status != http.StatusOK {
449			t.Fatalf("valid batch: %d %v", status, out)
450		} else if int(number(out["created"])) != 11 {
